"""The provenance stamp every generated file carries.

The stamp is five keys in the file's frontmatter ``metadata``: the host and its
release, the ``pkgskills`` release that rendered it, the install mode, and a note
that ``install`` overwrites edits. A rule or agent whose source has no frontmatter
gains a block to hold them. They are structured, so a reader and a tool can each
take one fact without parsing prose. The harness strips frontmatter before a rule
reaches the model, and takes a skill's into its own index, so the stamp costs no
context.

``metadata`` is the only slot the Agent Skills specification leaves for
properties it does not define, and its reference validator rejects any other
top-level key. So the keys share the map with whatever the source declares, and
the ``pkgskills-`` prefix keeps the two owners apart:
:meth:`~pkgskills.spec.SkillSpec.check_stampable` rejects a source that claims the
prefix. A source's own ``metadata.version`` still means the skill's version and
passes through verbatim.

Both version values are masked before a drift comparison, so a routine upgrade
of either package never flags a file whose content did not change. A
source-declared version is not masked -- when it changes, the stub should drift.

A file carrying an older stamp line counts as generated, and reads ``drifted``
until a bare ``install`` rewrites it. There are two sources of those lines.
``pkgskills`` itself wrote an HTML comment until the stamp moved here, and a host
that stamped its own files before it adopted ``pkgskills`` can declare those lines
on :attr:`Host.legacy_stamps <pkgskills.host.Host.legacy_stamps>`. Their versions
are not masked: the stamp differs from the current render, so such a file is
never ``ok`` however its body reads.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from importlib import metadata

import yaml

from pkgskills.frontmatter import FENCE, split_frontmatter
from pkgskills.host import MODES, Host, Mode
from pkgskills.spec import RESERVED_PREFIX

HOST_KEY = f"{RESERVED_PREFIX}host"
HOST_VERSION_KEY = f"{RESERVED_PREFIX}host-version"
VERSION_KEY = f"{RESERVED_PREFIX}version"
MODE_KEY = f"{RESERVED_PREFIX}mode"
NOTE_KEY = f"{RESERVED_PREFIX}note"
STAMP_KEYS = (HOST_KEY, HOST_VERSION_KEY, VERSION_KEY, MODE_KEY, NOTE_KEY)

#: A rule or agent has no body text saying this, and a bare ``install`` replaces
#: an edited file, so the warning travels with the stamp. Nothing reads it back.
NOTE = "generated; install overwrites edits"

_COMMENT_PREFIX = "<!-- generated by "
_COMMENT_REASON = (
    "stamped in an HTML comment by an earlier pkgskills; "
    "the stamp now lives in frontmatter"
)


def pkgskills_version() -> str:
    """The installed ``pkgskills`` version, or ``0.0.0`` when the record is absent."""
    try:
        return metadata.version("pkgskills")
    except metadata.PackageNotFoundError:
        return "0.0.0"


def render_stamp(host: Host, mode: Mode) -> str:
    """The stamp for ``host`` in ``mode``: its YAML lines, unindented.

    Values are quoted, since an unquoted ``0.7`` would read back as a float.
    """
    fields = (
        (HOST_KEY, host.dist),
        (HOST_VERSION_KEY, host.resolved_version()),
        (VERSION_KEY, pkgskills_version()),
        (MODE_KEY, mode),
        (NOTE_KEY, NOTE),
    )
    return "\n".join(f"{key}: {json.dumps(value)}" for key, value in fields)


def render_comment_stamp(host: Host, mode: Mode) -> str:
    """The HTML comment earlier releases wrote, for recognizing and testing it.

    Nothing writes this to a file any more.
    """
    return (
        f"{_COMMENT_PREFIX}{host.dist} {host.resolved_version()} "
        f"via pkgskills {pkgskills_version()} "
        f"(mode={mode}); do not edit. Regenerate with: "
        f"{host.install_command(mode, force=True)} -->"
    )


def _comment_re(dist: str) -> re.Pattern[str]:
    r"""A whole line in the comment form, recording any token as its mode.

    Whole, regenerate command included, so a line that merely begins like the
    stamp stays foreign. ``\w+`` takes a corrupted token for
    :func:`_legacy_match` to refuse.
    """
    return re.compile(
        rf"{re.escape(_COMMENT_PREFIX)}{re.escape(dist)} \S+ via pkgskills \S+ "
        r"\(mode=(?P<mode>\w+)\); do not edit\. Regenerate with: \S.* -->"
    )


_ANY_COMMENT_RE = re.compile(rf"(?m)^{re.escape(_COMMENT_PREFIX)}(\S+) ")


@dataclass(frozen=True)
class _LegacyStamp:
    """A stamp line pkgskills no longer writes, and why a file carrying it drifts."""

    pattern: re.Pattern[str]
    reason: str


def _legacy_entries(host: Host) -> tuple[_LegacyStamp, ...]:
    """Every older stamp form ``host``'s files may carry, in lookup order.

    The comment entry has no scheduled removal. A machine that skipped the release
    dropping it would read ``foreign`` on every file. If it ever goes, that
    release states the oldest version a bare-``install`` upgrade can start from.
    """
    return (
        _LegacyStamp(_comment_re(host.dist), _COMMENT_REASON),
        *(
            _LegacyStamp(pattern, f"stamped by {host.dist} before it adopted pkgskills")
            for pattern in host.legacy_stamps
        ),
    )


def _as_mode(token: str | None) -> Mode | None:
    """``token`` as an install mode, or ``None`` when it does not name one."""
    for mode in MODES:
        if token == mode:
            return mode
    return None


# -- reading the block -------------------------------------------------------


def _view(inner: str) -> dict[object, object] | None:
    """A block's YAML with every scalar as written, or ``None`` if not a mapping."""
    try:
        parsed = yaml.load(inner, Loader=yaml.BaseLoader)
    except yaml.YAMLError:
        return None
    return parsed if isinstance(parsed, dict) else None


def _recorded(text: str) -> dict[str, str]:
    """The stamp keys in ``text``'s frontmatter ``metadata``, as written."""
    front, _ = split_frontmatter(text)
    view = _view(front.inner) if front is not None else None
    found = view.get("metadata") if view is not None else None
    if not isinstance(found, dict):
        return {}
    return {
        key: value
        for key, value in found.items()
        if isinstance(key, str)
        and key.startswith(RESERVED_PREFIX)
        and isinstance(value, str)
    }


def _metadata_node(inner: str) -> yaml.MappingNode | None:
    """The node of a block's ``metadata`` mapping, or ``None`` when it has none.

    The node carries the source positions a text splice needs, which a parsed
    value has lost. The last key wins, as it does when YAML is loaded.
    """
    try:
        root = yaml.compose(inner, Loader=yaml.BaseLoader)
    except yaml.YAMLError:
        return None
    if not isinstance(root, yaml.MappingNode):
        return None
    found: yaml.Node | None = None
    for key, value in root.value:
        if key.value == "metadata":
            found = value
    return found if isinstance(found, yaml.MappingNode) else None


def _current_mode(text: str, host: Host) -> Mode | None:
    """The mode a whole, well-formed stamp for ``host`` records, else ``None``."""
    fields = _recorded(text)
    if fields.get(HOST_KEY) != host.dist:
        return None
    if not fields.get(HOST_VERSION_KEY) or not fields.get(VERSION_KEY):
        return None
    return _as_mode(fields.get(MODE_KEY))


def _legacy_match(text: str, host: Host) -> tuple[Mode, str] | None:
    """The recorded mode and reason of the first legacy entry ``text`` matches.

    Each pattern has to match a whole line, and only a newline ends one:
    ``splitlines`` would also break on a form feed or U+2028 and let a stamp with
    prose after it pass. A line whose ``mode`` group captured anything but an
    install mode is no match, so a pattern loose enough to take a corrupted token
    leaves that file ``foreign``. A file carrying a current stamp is not a legacy
    one, whatever else its body quotes.
    """
    if _current_mode(text, host) is not None:
        return None
    lines = text.split("\n")
    for entry in _legacy_entries(host):
        for line in lines:
            match = entry.pattern.fullmatch(line)
            mode = _as_mode(match.group("mode")) if match else None
            if mode is not None:
                return mode, entry.reason
    return None


def legacy_reason(text: str, host: Host) -> str | None:
    """Why ``text``'s legacy stamp drifts, or ``None`` when it carries none."""
    match = _legacy_match(text, host)
    return match[1] if match else None


def is_stamped(text: str, host: Host) -> bool:
    """True when ``text`` carries a stamp written for ``host``.

    Read from the frontmatter block, so a hand-written file whose body merely
    quotes the keys is never mistaken for a generated one. A whole line in an
    older form counts, whether ``pkgskills`` wrote it or the host declared it on
    ``legacy_stamps``.
    """
    return stamped_mode(text, host) is not None


def stamped_by(text: str) -> str | None:
    """The distribution ``text``'s stamp names, if any.

    Falls back to a comment line permanently, not only for the migration: a host
    on an older ``pkgskills`` keeps writing comments, and a foreign reason has to
    name that distribution.
    """
    named = _recorded(text).get(HOST_KEY)
    if named:
        return named
    match = _ANY_COMMENT_RE.search(text)
    return match.group(1) if match else None


def stamped_mode(text: str, host: Host) -> Mode | None:
    """The mode recorded in ``text``'s stamp, or ``None`` when unstamped."""
    mode = _current_mode(text, host)
    if mode is not None:
        return mode
    legacy = _legacy_match(text, host)
    return legacy[0] if legacy else None


def mask_versions(text: str, host: Host) -> str:
    """``text`` with both version values in ``host``'s stamp replaced by ``"*"``.

    Only those two values, located by their YAML nodes. A ``metadata.version`` a
    source declares is the skill's own, so a change to it is a real content
    change and has to drift, and a body quoting the keys is the body's own text.
    """
    front, body = split_frontmatter(text)
    if front is None or _recorded(text).get(HOST_KEY) != host.dist:
        return text
    inner = front.inner
    node = _metadata_node(inner)
    if node is None:  # pragma: no cover - a recorded host means the node exists
        return text
    spans = [
        (value.start_mark.index, value.end_mark.index)
        for key, value in node.value
        if key.value in (HOST_VERSION_KEY, VERSION_KEY)
    ]
    for start, end in sorted(spans, reverse=True):
        inner = f'{inner[:start]}"*"{inner[end:]}'
    return f"{FENCE}\n{inner}{FENCE}\n{body}"


# -- writing the block -------------------------------------------------------


def _block_end(inner: str, node: yaml.MappingNode) -> int:
    """Where a block mapping's last line ends in ``inner``.

    The node ends at the next key, past any blank lines and top-level comments,
    which belong to what follows. An indented comment stays in the mapping.
    """
    end = inner.rfind("\n", 0, node.end_mark.index) + 1
    while end:
        start = inner.rfind("\n", 0, end - 1) + 1
        line = inner[start:end]
        if line.strip() and not line.startswith("#"):
            break
        end = start
    return end


def _splice(inner: str, stamp: str) -> str:
    """``inner`` with the stamp's keys after the ones in its ``metadata``.

    A source's own lines stay byte for byte, whichever form its map takes. A flow
    map takes the keys inside its braces, and any other block gains a new map.
    """
    lines = stamp.splitlines()
    node = _metadata_node(inner)
    if node is None:
        return inner + "metadata:\n" + "".join(f"  {line}\n" for line in lines)
    if node.flow_style:
        close = node.end_mark.index - 1
        head = inner[:close].rstrip()
        sep = "" if head.endswith(("{", ",")) else ", "
        return f"{head}{sep}{', '.join(lines)}{inner[close:]}"
    indent = " " * node.value[0][0].start_mark.column
    end = _block_end(inner, node)
    added = "".join(f"{indent}{line}\n" for line in lines)
    return inner[:end] + added + inner[end:]


def _require_intact(before: str, after: str, stamp: str) -> None:
    """Raise unless ``after`` reads as ``before`` plus the stamp's keys, and no more.

    A text splice into YAML can go wrong in ways that still parse: an aliased map
    changes a second key, and a trailing block scalar changes value. The file
    would then install with altered content or read ``foreign`` straight after.
    """
    old = _view(before) or {}
    new = _view(after)
    own = old.get("metadata", {})
    fields = _view(stamp)
    if (
        new is None
        or not isinstance(own, dict)
        or fields is None
        or new != {**old, "metadata": {**own, **fields}}
    ):
        raise ValueError(
            "cannot add the provenance stamp to this frontmatter block; "
            f"write it as a plain block mapping:\n{before}"
        )


def stamp_fits(inner: str) -> bool:
    """True when the stamp can join a block's YAML without changing what it says.

    The conformance checks ask this, so a source :func:`place_stamp` would refuse
    fails in the host's own suite rather than at a consumer's ``install``. The
    answer does not depend on the stamp's values, which are always quoted.
    """
    probe = "\n".join(f'{key}: "0"' for key in STAMP_KEYS)
    try:
        _require_intact(inner, _splice(inner, probe), probe)
    except ValueError:
        return False
    return True


def place_stamp(front: str, stamp: str, body: str) -> str:
    """A whole file: frontmatter carrying ``stamp``, then a body.

    ``front`` is the raw block including its fences, or empty when the source has
    none, in which case the file gains a block. Raises ``ValueError`` when the
    stamp cannot join the block without changing what the block already says.
    """
    parsed, _ = split_frontmatter(front)
    inner = parsed.inner if parsed is not None else ""
    spliced = _splice(inner, stamp)
    _require_intact(inner, spliced, stamp)
    body = body.lstrip("\n")
    return f"{FENCE}\n{spliced}{FENCE}\n\n{body}"
